CREATE TABLE IF NOT EXISTS "worm" (
	"id" INTEGER PRIMARY KEY,
	"name" TEXT NOT NULL UNIQUE
);
INSERT INTO "worm" ("id", "name") VALUES (1, 'LYSARETE_BRASILIENSIS'), (2, 'STRONGYLOIDES_STERCORALIS')
ON CONFLICT ("id") DO UPDATE SET "name" = excluded."name";

CREATE TABLE IF NOT EXISTS "claw" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"side" TEXT NOT NULL,
	"size_cm" INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS "crab" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"name" TEXT NOT NULL,
	"species" TEXT NOT NULL,
	"habitat" TEXT NOT NULL,
	"length_segments" BIGINT NOT NULL,
	"weight_grams" BIGINT NOT NULL,
	"age_years" SMALLINT NOT NULL,
	"claw_span_cm" INTEGER NOT NULL,
	"color" TEXT NOT NULL,
	"is_nocturnal" BOOLEAN NOT NULL,
	"is_alive" BOOLEAN NOT NULL
);

CREATE TABLE IF NOT EXISTS "crab_worms" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"crab_id" INTEGER NOT NULL REFERENCES "crab"("id") ON DELETE CASCADE,
	"position" INTEGER NOT NULL,
	"value_id" INTEGER NOT NULL REFERENCES "worm"("id")
);

CREATE TABLE IF NOT EXISTS "crab_nicknames" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"crab_id" INTEGER NOT NULL REFERENCES "crab"("id") ON DELETE CASCADE,
	"position" INTEGER NOT NULL,
	"value" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "crab_claws" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"crab_id" INTEGER NOT NULL REFERENCES "crab"("id") ON DELETE CASCADE,
	"position" INTEGER NOT NULL,
	"value_id" INTEGER NOT NULL REFERENCES "claw"("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "user" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"name" TEXT NOT NULL,
	"email" TEXT NOT NULL,
	"age" SMALLINT NOT NULL,
	"is_active" BOOLEAN NOT NULL
);